import{_ as n,o as t,c as i,a2 as o}from"./chunks/framework.DpXDHk3d.js";const p=JSON.parse('{"title":"8.2 电动机的工作原理","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-2-dian-dong-ji-de-gong-zuo-yuan-li.md","filePath":"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-2-dian-dong-ji-de-gong-zuo-yuan-li.md","lastUpdated":1793095197000}'),l={name:"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-2-dian-dong-ji-de-gong-zuo-yuan-li.md"};function e(s,a,r,u,d,g){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="_8-2-电动机的工作原理" tabindex="-1">8.2 电动机的工作原理 <a class="header-anchor" href="#_8-2-电动机的工作原理" aria-label="Permalink to &quot;8.2 电动机的工作原理&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电动机为什么会转?一句话:<strong>三相交流电 → 旋转磁场 → 转子被&quot;拖着&quot;转</strong>。这一节讲清这四步,以及最重要的概念——<strong>转差率</strong>。理解了转差率,才算真正懂&quot;异步&quot;二字。</p><h2 id="一、旋转磁场怎么来的" tabindex="-1">一、旋转磁场怎么来的 <a class="header-anchor" href="#一、旋转磁场怎么来的" aria-label="Permalink to &quot;一、旋转磁场怎么来的&quot;">​</a></h2><p>定子三相绕组在空间上<strong>相差 120°<strong>分布,通入三相交流电后,三个绕组的磁场随时间变化又互相叠加,合成一个</strong>大小不变、位置不断旋转</strong>的磁场——这就是<strong>旋转磁场</strong>。</p><ul><li>旋转磁场的转速叫<strong>同步转速</strong>,用 n₁(或 ns)表示;</li><li>同步转速与电源频率 f 和磁极对数 p 有关:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>n₁ = 60 × f / p</span></span></code></pre></div><ul><li>f = 50 Hz,磁极对数 p = 1(两极电机)时,<code>n₁ = 60 × 50 / 1 = 3000 r/min</code>;</li><li>p = 2(四极电机)时,<code>n₁ = 1500 r/min</code>。</li></ul><blockquote><p>💡 记忆:<strong>电源频率越高、磁极越少,同步转速越快</strong>。</p></blockquote><h2 id="二、转子怎么转起来-四步" tabindex="-1">二、转子怎么转起来(四步) <a class="header-anchor" href="#二、转子怎么转起来-四步" aria-label="Permalink to &quot;二、转子怎么转起来(四步)&quot;">​</a></h2><ol><li><strong>定子产生旋转磁场</strong>;</li><li>旋转磁场<strong>切割转子导条</strong> → 转子导条中感应出<strong>感应电流</strong>(电磁感应);</li><li>通电的转子导条处在磁场中 → 受到<strong>安培力</strong>;</li><li>转子在力作用下<strong>跟随磁场转动</strong>。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三相交流电 ─► 定子旋转磁场 ─► 转子感应电流 ─► 转子受力转动</span></span></code></pre></div><blockquote><p>💡 通俗比喻:旋转磁场像一根&quot;转动的磁棒&quot;,磁棒转起来,把旁边能导电的&quot;鼠笼&quot;带着转——这就是电动机&quot;被磁场带着跑&quot;的原理。</p></blockquote><h2 id="三、转差率-核心概念-必背" tabindex="-1">三、转差率(核心概念,必背) <a class="header-anchor" href="#三、转差率-核心概念-必背" aria-label="Permalink to &quot;三、转差率(核心概念,必背)&quot;">​</a></h2><p><strong>转差率 s</strong>:描述转子转速 n 与同步转速 n₁ 的&quot;差距&quot;:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s = (n₁ - n) / n₁</span></span></code></pre></div><ul><li>正常运行时,转子转速 <strong>n 永远略小于同步转速 n₁</strong>(转差率 s 很小,如 2%~5%);</li><li>因为转子必须&quot;追不上&quot;磁场,才能一直有磁通切割、一直有感应电流、一直有转动力矩——所以叫<strong>异步</strong>电动机;</li><li>若 n = n₁(s = 0),就没有相对运动、没有感应电流,转子反而<strong>转不起来</strong>。</li></ul><blockquote><p>⚠️ 高频考点:<strong>异步电动机的转子转速小于同步转速</strong>;&quot;异步&quot;就是这个&quot;差&quot;的由来。</p></blockquote><h2 id="四、额定转速与转差" tabindex="-1">四、额定转速与转差 <a class="header-anchor" href="#四、额定转速与转差" aria-label="Permalink to &quot;四、额定转速与转差&quot;">​</a></h2><ul><li>电机铭牌上的<strong>额定转速</strong>就是正常负载下的转子转速;</li><li>例:四极电机(同步 1500 r/min)额定转速常为 1440 r/min 左右,转差率约 4%。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 同步转速 <code>n₁ = 60f/p</code>(f 越大、p 越小,转速越快)。</li><li>✅ <strong>转子转速 &lt; 同步转速</strong>——这是&quot;异步&quot;的含义。</li><li>✅ 转差率 s = (n₁−n)/n₁,正常很小(约 2%~5%)。</li><li>⚠️ 易混点:同步转速(磁场转速)与转子转速(实际转速)是两个数,别混。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>三相交流电产生旋转磁场,转子靠感应电流受力转动。</li><li>同步转速 n₁ = 60f/p;转子转速 n 永远小于 n₁。</li><li>转差率 s = (n₁−n)/n₁,是异步电动机的&quot;标志&quot;。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)同步转速 n₁ = 60f/p 中,对于电源频率 50 Hz、磁极对数 p=2 的电动机,同步转速约为()。 A. 3000 r/min　B. 1500 r/min　C. 1000 r/min　D. 750 r/min</li><li>(判断)三相异步电动机的转子转速小于同步转速。( )</li><li>(单选)转差率 s = (n₁−n)/n₁,正常运行时 s 的值()。 A. 较大(接近 1)　B. 很小　C. 等于 0　D. 大于 1</li><li>(判断)三相交流电通入定子绕组,会产生旋转磁场。( )</li><li>(单选)转子转不起来的根本原因是()。 A. 磁场不转　B. 转子和磁场转速相等(s=0)　C. 转子太重　D. 电压太低</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。n₁ = 60 × 50 / 2 = 1500 r/min。</li><li><strong>√</strong>。异步电动机转子转速小于同步转速。</li><li><strong>B</strong>。正常转差率很小(约 2%~5%)。</li><li><strong>√</strong>。三相交流电产生旋转磁场。</li><li><strong>B</strong>。转子与磁场无相对运动(s=0)时无感应电流,转不起来。</li></ol></details>',27)])])}const h=n(l,[["render",e]]);export{p as __pageData,h as default};
